using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class CaptureVehicleFrames {
 static string folder;static GameObject stage,actor;static Camera camera;static RenderTexture rt;static Animator animator;static Chapter45RiderPose pose;static int waitFrame,lastFrame=-1;static Queue<(string kind,float phase,int view)> jobs;static List<object> rows;static Dictionary<string,GameObject> sources;
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 public static object Main(string output){if(!EditorApplication.isPlaying)throw new Exception("Play required");folder=output;Directory.CreateDirectory(folder);rows=new();jobs=new();var d=Object.FindFirstObjectByType<Chapter45Director>();sources=d.hazards.Where(h=>h.name.Contains("kickboard")||h.name.Contains("motorcycle")).GroupBy(h=>h.name.Contains("kickboard")?"Kickboard":"DeliveryBike").ToDictionary(g=>g.Key,g=>g.First().body.Find("Generated vehicle and own rig rider").gameObject);foreach(string kind in sources.Keys)foreach(float phase in new[]{0f,.25f,.5f,.75f})foreach(int view in new[]{0,1})jobs.Enqueue((kind,phase,view));stage=new GameObject("Temporary generated vehicle frame review");rt=new RenderTexture(1024,768,24);var cg=new GameObject("Temporary vehicle review camera");cg.transform.SetParent(stage.transform,false);camera=cg.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.35f,.38f);camera.orthographic=true;camera.orthographicSize=1.35f;camera.nearClipPlane=.1f;camera.farClipPlane=25;camera.targetTexture=rt;waitFrame=-1;EditorApplication.update+=Tick;return new{folder,frames=jobs.Count,pending=true};}
 static void Tick(){if(Time.frameCount==lastFrame)return;lastFrame=Time.frameCount;try{if(jobs.Count==0){Finish(null);return;}var job=jobs.Peek();if(waitFrame<0){if(actor==null||actor.name!=job.kind){if(actor!=null)Object.DestroyImmediate(actor);actor=Object.Instantiate(sources[job.kind],stage.transform);actor.name=job.kind;actor.transform.localPosition=Vector3.zero;actor.transform.localRotation=Quaternion.identity;foreach(var t in actor.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;pose=actor.GetComponent<Chapter45RiderPose>();pose.enabled=false;animator=pose.animator;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;actor.SetActive(true);}animator.enabled=true;animator.speed=0;animator.Play("idle",0,job.phase);animator.Update(0);animator.enabled=false;pose.ApplyPose();camera.transform.localPosition=job.view==0?new Vector3(3,2.1f,5):new Vector3(5,1.7f,.1f);camera.transform.LookAt(Vector3.up*1.0f);waitFrame=Time.frameCount+3;return;}pose.ApplyPose();if(Time.frameCount<waitFrame)return;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(1024,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1024,768),0,0);png.Apply();string file=job.kind+"-"+job.phase.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+"-view"+job.view+".png";File.WriteAllBytes(Path.Combine(folder,file),png.EncodeToPNG());Object.DestroyImmediate(png);RenderTexture.active=old;rows.Add(new{job.kind,job.phase,job.view,file,frame=Time.frameCount,leftHandGap=Vector3.Distance(pose.leftHand.position,pose.leftGrip.position),rightHandGap=Vector3.Distance(pose.rightHand.position,pose.rightGrip.position),seatGap=pose.seat!=null?Vector3.Distance(pose.hips.position,pose.seat.position):0});jobs.Dequeue();waitFrame=-1;}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string error){EditorApplication.update-=Tick;if(stage!=null)Object.DestroyImmediate(stage);if(rt!=null){rt.Release();Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(folder,"result.json"),Json(new{completed=error==null,error,frames=rows,conditions="Actual Unity Play rendering of installed generated vehicles/own rig rider clips and pose attachments; sampled pose fixture, not ordinary hazard traversal."}));}
}
